function fireFileInputFromImg(e){$("#uploader-image-"+e).click()}function readURL(e,a){if(e.files&&e.files[0]){var i=new FileReader;i.onload=function(e){$("#uploader-image-container-"+a).css("background-image","url("+e.target.result+")")},i.readAsDataURL(e.files[0])}}$(document).ready(function(){$("[id^='uploader-image-']").change(function(){let e=$(this).attr("id").replace("uploader-image-","");readURL(this,e),$("#file-name-to-upload-"+e).val($(this).val().replace(/C:\\fakepath\\/i,"")),$("#image-to-upload-url-"+e).val("")})});